export interface AnimationParams {
  /** 歩行 1 コマの時間 (素材 v0.2 のプレビューで確認した値)。 */
  walkFrameMs: number;
  /** 眠りへ移るコマ / 目覚めるコマの時間。 */
  sleepFrameMs: number;
  wakeFrameMs: number;
  /** 待機中の瞬きの間隔 (最小・最大) と長さ。 */
  blinkEveryMs: [number, number];
  blinkMs: number;
  /** 表示・非表示のフェード時間 (CSS と合わせる)。 */
  fadeMs: number;
  /** 駆け足 1 コマの時間 (歩行コマを速く再生する)。 */
  runFrameMs: number;
  /** その場で跳ねる高さと 1 回の時間。喜ぶときは 2 回。 */
  hopHeight: number;
  hopMs: number;
  /** ジャンプの頂点の高さ (踏切・着地のどちらか高い方から) と、水平 1px あたりの時間。 */
  jumpApex: number;
  jumpMsPerPx: number;
  jumpMinMs: number;
  /** カード裏へ沈む・顔を出す時間と、顔を出すときに見せる高さ (耳と目)。 */
  sinkMs: number;
  peekVisible: number;
  /** 周囲を見るときに向きを変える間隔 (最小・最大)。 */
  lookTurnMs: [number, number];
  /** 縁にしがみついている長さ (最小・最大)。後ろ足をバタバタさせてから、よじ登る。 */
  hangMs: [number, number];
  /** カーソルにぶら下がっている最長の時間と、跳びついて戻る 1 回の時間。 */
  cursorHangMs: [number, number];
  cursorLeapMs: number;
}

