export interface TerrainParams {
  /** キャラクターの上・左右に空ける余白 (CSS px)。文字や操作部品にぎりぎりまで寄せない。 */
  clearanceTop: number;
  clearanceSide: number;
  /** 足場の角 (角丸) を避ける最小の内側余白 (CSS px)。 */
  cornerInset: number;
  /**
   * 同じ段の足場を 1 本につなぐのに必要な、角丸の内側 (両端から cornerInset を除いた範囲) どうしの重なり (CSS px)。
   * カードの中の同じ高さの枠などだけをつなぐ。隙間のある・角丸どうしが接する・浅く重なるだけの継ぎ目はつながない
   * (つなぐと、隙間と角丸の上を足元の高さが変わらないまま歩いて、空中を踏んで見える)。継ぎ目は、安全なジャンプで
   * 渡るか、その手前で止まる。
   */
  minJoinOverlap: number;
  /** 同じ高さの段とみなす上辺の差 (CSS px)。ホバーで 2px 浮いたタイルも同じ列のまま歩ける。 */
  rowTolerance: number;
  /** 足場として使う最小の幅 (可視部分 + 余白)。 */
  minSegmentWidth: number;
  /** ジャンプできる水平の隙間・上る高さ・下りる高さの上限 (CSS px)。 */
  jumpMaxGap: number;
  jumpMaxRise: number;
  jumpMaxDrop: number;
}

export const DEFAULT_TERRAIN: TerrainParams = {
  clearanceTop: 3,
  clearanceSide: 4,
  cornerInset: 12,
  minJoinOverlap: 1,
  rowTolerance: 3,
  minSegmentWidth: SPRITE.width + 8,
  jumpMaxGap: 110,
  jumpMaxRise: 48,
  jumpMaxDrop: 90,
};

export interface TimingParams {
  /** 画面の表示後、登場するまでの待ち時間 (入場アニメーションが落ち着いてから計測する)。 */
  enterDelayMs: [number, number];
  /** DOM の変化・リサイズのあと、計測し直すまでの待ち時間。 */
  remeasureDebounceMs: number;
  /** スクロールが止まったと判断するまでの時間。 */
  scrollIdleMs: number;
  /** 眠っているときに操作があったら目覚める確率 (気まぐれ)。 */
  wakeOnActivityChance: number;
}

/** 触れ合い (タップ・クリック・カーソル・スクロール) の判定と反応の調整値。 */
export interface InteractionParams {
  /** 短いタップとみなす押下の長さ・指の移動の上限。 */
  tapMaxMs: number;
  tapMaxMove: number;
  /** 触れた判定を表示枠より広げる量 (CSS px)。 */
  touchSlop: number;
  /** 背後 (しっぽ側の外) とみなす幅。 */
  behindWidth: number;
  /** 近くのタップに近づく範囲と確率。近づかないときに首をかしげる確率。 */
  approachRange: number;
  approachChance: number;
  nearTiltChance: number;
  /** この時間内にこの回数触られたら逃げる。 */
  fleeWindowMs: number;
  fleeTouches: number;
  /** 反応のあと、次の反応まで空ける時間 (反応しっぱなしにしない)。 */
  reactionCooldownMs: number;
  /** PC のカーソル: 近いとみなす距離、静止とみなす時間、近づく・のぞく確率、判定の間隔。 */
  cursorNear: number;
  cursorStillMs: number;
  cursorApproachChance: number;
  cursorPeekChance: number;
  cursorCheckMs: number;
  /** ぶら下がっている間に、カーソルがこれ以上動いたら放す (CSS px)。 */
  cursorReleaseMove: number;
  /** 速いカーソル・速いスクロールとみなす速さ (CSS px / 秒)。 */
  fastCursor: number;
  fastScroll: number;
}

